def solve(I):
    H,W=len(I),len(I[0]); h,w=H//2,W//2
    qs={'TL':(0,h,0,w),'TR':(0,h,w,W),'BL':(h,H,0,w),'BR':(h,H,w,W)}
    bgs={q:Counter(I[i][j] for i in range(r0,r1) for j in range(c0,c1)).most_common(1)[0][0]
         for q,(r0,r1,c0,c1) in qs.items()}
    gcnt=Counter(x for r in I for x in r)
    out=[]
    for i in range(h):
        row=[]
        for j in range(w):
            vals=[I[r][c] for q,(r0,r1,c0,c1) in qs.items() for r,c in [(i+r0,j+c0)]]
            nb=[v for v,bg in zip(vals,bgs.values()) if v!=bg]
            if not nb: row.append(bgs[list(qs)[list(vals).index(vals[0])]]); continue
            cnt=Counter(nb)
            mx=max(cnt.values())
            cands=[c for c,v in cnt.items() if v==mx]
            row.append(gcnt.most_common(1)[0][0] if len(cands)>1 else cands[0])
        out.append(row)
    return out

